('spAuxiliares_FiltrarAuxiliares', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Filtra auxiliares aplicando criterios de búsqueda opcionales.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> con múltiples <strong style="color: #dc3545; font-weight: 600;">JOINs</strong>: <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoDocumentos</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbRubros</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTiposAuxiliares</code>, y <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbUsuarios</code>.</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Aplica filtros dinámicos WHERE:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@Busqueda busca en nombre, apellido, descripción de rubro/tipo, número de identificación, y cuenta formateada usando <strong style="color: #dc3545; font-weight: 600;">LIKE</strong> con comodines</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@TipoAuxiliar filtra por ID del auxiliar</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@CodigoRubro filtra por código de rubro</span></div><p style="margin-bottom: 14px; text-align: justify;">Solo muestra auxiliares y asociados no eliminados (snEliminado = 0).</p><p style="margin-bottom: 14px; text-align: justify;">Retorna información completa similar a <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spAuxiliares_ObtenerAuxiliares</code>. Ordena por ID descendente.</p></div>',
NULL, 'tbAuxiliares, tbAsociados, tbTipoDocumentos, tbRubros, tbTiposAuxiliares, tbUsuarios', GETDATE(), 0),

('spAuxiliares_EliminarAuxiliar', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Elimina lógicamente un auxiliar (soft delete).</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Realiza 3 validaciones:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que ID y NumeroAsociado sean requeridos</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que el auxiliar exista en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code></span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que no tenga movimientos asociados en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbMovimientos</code> (si tiene movimientos, no permite eliminar)</span></div><p style="margin-bottom: 14px; text-align: justify;">Utiliza transacciones (<strong style="color: #dc3545; font-weight: 600;">BEGIN TRANSACTION</strong>/<strong style="color: #dc3545; font-weight: 600;">COMMIT</strong>) para garantizar integridad.</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> estableciendo snEliminado = 1, FechaElimina = GETDATE(), UsuarioElimina, y SysLastSessionID.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Retorna ''SUCCESS'' o ''ERROR'' con mensaje descriptivo.</p></div>',
NULL, 'tbAuxiliares, tbMovimientos', GETDATE(), 0),

('spAuxiliares_ActivarDesactivar', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Activa o desactiva un auxiliar cambiando su estado.</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Realiza 3 validaciones:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que ID y NumeroAsociado sean requeridos</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que el auxiliar exista en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code></span></div><p style="margin-bottom: 14px; text-align: justify;">Utiliza transacciones (<strong style="color: #dc3545; font-weight: 600;">BEGIN TRANSACTION</strong>/<strong style="color: #dc3545; font-weight: 600;">COMMIT</strong>).</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> estableciendo snActivo = @snActivo (1 para activar, 0 para desactivar), FechaModificacion = GETDATE(), UsuarioModifica, y SysLastSessionID.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Retorna mensaje de éxito indicando si fue activado o desactivado.</p></div>',
NULL, 'tbAuxiliares', GETDATE(), 0),

('spAuxiliares_ModificarMontoPignorado', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Modifica el monto pignorado de un auxiliar específico.</p><p style="margin-bottom: 14px; text-align: justify;">Valida que el auxiliar exista y pertenezca al asociado especificado en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> actualizando MontoPignorado = @NuevoMonto, FechaModificacion = GETDATE(), UsuarioModifica, y SysLastSessionID.</p><p style="margin-bottom: 14px; text-align: justify;">Verifica que la actualización se realizó correctamente usando @@ROWCOUNT.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Retorna mensaje de éxito.</p></div>',
NULL, 'tbAuxiliares', GETDATE(), 0),

('spAuxiliares_CalcularIntereses', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Calcula los intereses pendientes de un auxiliar de préstamo.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> para obtener datos del préstamo (TasaInteres, Saldo, FechaUltCalculoInteres).</p><p style="margin-bottom: 14px; text-align: justify;">Calcula los intereses desde la última fecha de cálculo hasta la fecha actual.</p><p style="margin-bottom: 14px; text-align: justify;">Actualiza los campos InteresCalculado y FechaUltCalculoInteres en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna mensaje de error si hay algún problema.</p><p style="margin-bottom: 14px; text-align: justify;">Utilizado por <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spMovimientos_GuardarMovimiento</code> para calcular intereses antes de procesar un pago.</p></div>',
NULL, 'tbAuxiliares', GETDATE(), 0),

('spAuxiliares_ObtenerHistorialIntereses', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene el historial de cálculo de intereses de un auxiliar.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta la tabla de historial de intereses o <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code> para obtener información sobre cuándo se calcularon intereses, montos calculados, y pagos realizados.</p><p style="margin-bottom: 14px; text-align: justify;">Utilizado para mostrar el detalle de intereses en la interfaz.</p></div>',
NULL, 'tbAuxiliares', GETDATE(), 0),

-- Buscar Asociados
('spBuscarAsociadoPorID', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Busca un asociado específico por su número de asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> con <strong style="color: #dc3545; font-weight: 600;">JOINs</strong> a <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoAsociado</code> y <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoDocumentos</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna información básica: NumeroAsociado, NombreCompleto (concatenado), NumeroIdentificacion, tipo de documento, tipo de asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Además, cuenta los auxiliares activos del asociado usando subconsulta a <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>, y retorna los auxiliares en formato JSON mediante una subconsulta a la vista <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">vwAuxiliaresPorAsociados</code> con <strong style="color: #dc3545; font-weight: 600;">FOR JSON AUTO</strong>.</p><p style="margin-bottom: 14px; text-align: justify;">Solo muestra asociados no eliminados (snEliminado = 0). Ordena por nombre y apellido.</p></div>',
NULL, 'tbAsociados, tbTipoAsociado, tbTipoDocumentos, tbAuxiliares, vwAuxiliaresPorAsociados', GETDATE(), 0),

('spBuscarAsociados', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Busca asociados aplicando criterios de búsqueda parcial.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> con <strong style="color: #dc3545; font-weight: 600;">JOINs</strong> a <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoAsociado</code> y <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoDocumentos</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Aplica búsqueda con <strong style="color: #dc3545; font-weight: 600;">LIKE</strong> en múltiples campos: Nombre, SegundoNombre, Apellido, SegundoApellido, NumeroIdentificacion, y NumeroAsociado (convertido a VARCHAR).</p><p style="margin-bottom: 14px; text-align: justify;">Retorna <strong style="color: #dc3545; font-weight: 600;">TOP 10</strong> resultados con información básica: NumeroAsociado, NombreCompleto, NumeroIdentificacion, tipo de documento, tipo de asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Cuenta los auxiliares activos del asociado y retorna los auxiliares en formato JSON mediante subconsulta a la vista <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">vwAuxiliaresPorAsociados</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Solo muestra asociados no eliminados (snEliminado = 0). Ordena por nombre y apellido.</p></div>',
NULL, 'tbAsociados, tbTipoAsociado, tbTipoDocumentos, tbAuxiliares, vwAuxiliaresPorAsociados', GETDATE(), 0),

-- Gestión de Socios
('spGestionSocios_ObtenerSocios', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene una lista de socios aplicando múltiples filtros opcionales.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> con múltiples <strong style="color: #dc3545; font-weight: 600;">LEFT JOINs</strong>: <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoAsociado</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbUsuarios</code> (creador y modificador), <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbEmpresas</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbOcupaciones</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbPaises</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbProvincias</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbDistritos</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbCorregimientos</code>.</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Aplica filtros dinámicos WHERE:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@FiltroNombre busca con <strong style="color: #dc3545; font-weight: 600;">LIKE</strong> en Nombre, Apellido, SegundoNombre, SegundoApellido</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@FiltroTipo filtra por IdTipoAsociado</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@FiltroEstatus filtra por Estatus</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@FiltroTipoDocumento filtra por TipoIdentificacion</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>@FiltroIdentificacion busca con <strong style="color: #dc3545; font-weight: 600;">LIKE</strong> en NumeroIdentificacion</span></div><p style="margin-bottom: 14px; text-align: justify;">Solo muestra socios no eliminados (snEliminado = 0). Cuenta los auxiliares activos del socio.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna información completa del socio incluyendo datos personales, contacto, ubicación, laborales, y descripciones de las entidades relacionadas.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Ordena por NumeroAsociado descendente.</p></div>',
NULL, 'tbAsociados, tbTipoAsociado, tbUsuarios, tbEmpresas, tbOcupaciones, tbPaises, tbProvincias, tbDistritos, tbCorregimientos, tbAuxiliares', GETDATE(), 0),

('spGestionSocios_ObtenerSocioPorNumero', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene información completa de un socio específico por su número de asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> con los mismos múltiples <strong style="color: #dc3545; font-weight: 600;">LEFT JOINs</strong> que <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spGestionSocios_ObtenerSocios</code>: <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbTipoAsociado</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbUsuarios</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbEmpresas</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbOcupaciones</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbPaises</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbProvincias</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbDistritos</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbCorregimientos</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Filtra por NumeroAsociado específico y solo muestra socios no eliminados (snEliminado = 0).</p><p style="margin-bottom: 14px; text-align: justify;">Retorna información completa del socio incluyendo todos los datos personales, de contacto, ubicación, laborales, y descripciones de las entidades relacionadas.</p><p style="margin-bottom: 14px; text-align: justify;">Cuenta los auxiliares activos del socio. Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>.</p></div>',
NULL, 'tbAsociados, tbTipoAsociado, tbUsuarios, tbEmpresas, tbOcupaciones, tbPaises, tbProvincias, tbDistritos, tbCorregimientos, tbAuxiliares', GETDATE(), 0),

('spGestionSocios_CrearSocio', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Crea un nuevo socio en el sistema.</p><p style="margin-bottom: 14px; text-align: justify;"><strong style="color: #2c3e50;">Realiza validación de duplicados:</strong> verifica que no exista otro socio con el mismo NumeroIdentificacion y snEliminado = 0 en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code>. Si ya existe, retorna error.</p><p style="margin-bottom: 14px; text-align: justify;">Si no existe, realiza un <strong style="color: #dc3545; font-weight: 600;">INSERT</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> con todos los campos:</p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Datos personales (IdTipoAsociado, Nombre, Apellidos, Estatus, TipoIdentificacion, NumeroIdentificacion, Sexo, FechaNacimiento)</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Datos de contacto (teléfonos, CorreoElectronico)</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Datos de ubicación (Provincia, Distrito, Corregimiento, Dirección tanto de residencia como de trabajo)</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Datos laborales (LugarTrabajo, Ocupacion, NivelEstudio, Profesion)</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Países de residencia y trabajo</span></div><p style="margin-bottom: 14px; text-align: justify;">Establece FechaCreacion = GETDATE(), UsuarioCrea, SysLastSessionID, y snEliminado = 0.</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong> para manejo de errores. Retorna el NumeroAsociado creado usando <strong style="color: #dc3545; font-weight: 600;">SCOPE_IDENTITY()</strong>.</p></div>',
NULL, 'tbAsociados', GETDATE(), 0),

('spGestionSocios_ActualizarSocio', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Actualiza información de un socio existente.</p><p style="margin-bottom: 14px; text-align: justify;">Realiza validaciones similares a <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spGestionSocios_CrearSocio</code> para evitar duplicados de identificación.</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code> actualizando todos los campos: datos personales, contacto, ubicación, laborales.</p><p style="margin-bottom: 14px; text-align: justify;">Establece FechaModificacion = GETDATE() y UsuarioModifica.</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong> para manejo de errores.</p></div>',
NULL, 'tbAsociados', GETDATE(), 0),

('spGestionSocios_EliminarAsociado', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Elimina lógicamente un asociado del sistema (soft delete).</p><p style="margin-bottom: 14px; text-align: justify;">Realiza validaciones para verificar que el asociado exista y no tenga relaciones que impidan su eliminación.</p><p style="margin-bottom: 14px; text-align: justify;">Actualiza el campo snEliminado = 1 en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza transacciones y manejo de excepciones.</p></div>',
NULL, 'tbAsociados', GETDATE(), 0),

-- Beneficiarios
('spBeneficiarios_ObtenerBeneficiarios', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene todos los beneficiarios de un socio específico.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbBeneficiarios</code> con <strong style="color: #dc3545; font-weight: 600;">LEFT JOIN</strong> a <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbParentezcos</code> para obtener la descripción del parentesco.</p><p style="margin-bottom: 14px; text-align: justify;">Filtra por NumeroAsociado y solo muestra beneficiarios no eliminados (snEliminado = 0).</p><p style="margin-bottom: 14px; text-align: justify;">Retorna IDBeneficiario, NumeroAsociado, Nombre, Apellido, TipoIdentificacion, NumeroIdentificacion, IDParentezco, Porcentaje, y Parentezco.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Ordena por nombre y apellido.</p></div>',
NULL, 'tbBeneficiarios, tbParentezcos', GETDATE(), 0),

('spBeneficiarios_CrearBeneficiario', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Crea un nuevo beneficiario para un socio.</p><p style="margin-bottom: 14px; text-align: justify;"><strong style="color: #2c3e50;">Realiza validación crítica:</strong> calcula el porcentaje total de todos los beneficiarios existentes del asociado y verifica que al agregar el nuevo porcentaje no se exceda el 100%. Si excede, retorna error.</p><p style="margin-bottom: 14px; text-align: justify;">Si es válido, realiza un <strong style="color: #dc3545; font-weight: 600;">INSERT</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbBeneficiarios</code> con todos los campos: NumeroAsociado, Nombre, Apellido, TipoIdentificacion, NumeroIdentificacion, IDParentezco, Porcentaje, UsuarioCrea, FechaHoraCrea = GETDATE(), SysLastSessionID, y snEliminado = 0.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones con <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong>. Retorna ''SUCCESS'' o ''ERROR'' con mensaje.</p></div>',
NULL, 'tbBeneficiarios', GETDATE(), 0),

('spBeneficiarios_ActualizarBeneficiario', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Actualiza información de un beneficiario existente.</p><p style="margin-bottom: 14px; text-align: justify;">Similar a <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spBeneficiarios_CrearBeneficiario</code>, valida que el porcentaje total no exceda 100% considerando el porcentaje actualizado.</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbBeneficiarios</code> actualizando los campos del beneficiario.</p><p style="margin-bottom: 14px; text-align: justify;">Establece campos de auditoría de modificación.</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong> para manejo de errores.</p></div>',
NULL, 'tbBeneficiarios', GETDATE(), 0),

('spBeneficiarios_EliminarBeneficiario', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Elimina lógicamente un beneficiario (soft delete).</p><p style="margin-bottom: 14px; text-align: justify;">Realiza un <strong style="color: #dc3545; font-weight: 600;">UPDATE</strong> en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbBeneficiarios</code> estableciendo snEliminado = 1.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye campos de auditoría.</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza <strong style="color: #dc3545; font-weight: 600;">TRY-CATCH</strong> para manejo de errores.</p></div>',
NULL, 'tbBeneficiarios', GETDATE(), 0),

('spBeneficiarios_ObtenerParentezcos', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene todos los tipos de parentesco disponibles.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbParentezcos</code> filtrando por registros no eliminados.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna IDParentezco y Parentezco.</p><p style="margin-bottom: 14px; text-align: justify;">Utilizado para llenar dropdowns de selección de parentesco en formularios de beneficiarios.</p></div>',
NULL, 'tbParentezcos', GETDATE(), 0),

-- Movimientos
('spMovimientos_GuardarMovimiento', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Guarda un nuevo movimiento financiero en el sistema. Este SP tiene lógica compleja.</p><p style="margin-bottom: 14px; text-align: justify;">Primero llama a <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spMovimiento_Validar</code> para validar el movimiento (verifica saldos, límites, estado del auxiliar).</p><p style="margin-bottom: 14px; text-align: justify;">Si es un préstamo (CodigoRubro = ''PR''), llama a <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spAuxiliares_CalcularIntereses</code> para calcular intereses pendientes.</p><p style="margin-bottom: 14px; text-align: justify;">Luego inicia una transacción.</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Si hay intereses pendientes:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Crea dos movimientos separados: uno para intereses (que no afecta el saldo del auxiliar) y otro para capital (que sí afecta el saldo)</span></div><p style="margin-bottom: 14px; text-align: justify;">Si no hay intereses, crea solo el movimiento de capital.</p><p style="margin-bottom: 14px; text-align: justify;">Actualiza el saldo del auxiliar en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>.</p><p style="margin-bottom: 14px; text-align: justify;">Crea registros en <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbMovimientos</code> con los datos del movimiento.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna los IDs de los movimientos creados (CapitalMovimientoID e InteresesMovimientoID).</p><p style="margin-bottom: 14px; text-align: justify;">Utiliza transacciones para garantizar integridad. Incluye manejo completo de excepciones.</p></div>',
'spMovimiento_Validar, spAuxiliares_CalcularIntereses', 'tbMovimientos, tbAuxiliares', GETDATE(), 0),

('spMovimiento_Validar', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Valida si un movimiento puede ser realizado.</p><p style="margin-bottom: 14px;"><strong style="color: #2c3e50;">Validaciones realizadas:</strong></p><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica que el auxiliar exista, esté activo y no eliminado</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Valida que el código de transacción sea válido</span></div><div style="margin-bottom: 10px; padding-left: 24px; position: relative; padding-top: 2px;"><span style="position: absolute; left: 8px; color: #007bff; font-weight: bold; font-size: 18px; line-height: 1.2;">•</span> <span>Verifica saldos y límites según el tipo de transacción</span></div><p style="margin-bottom: 14px; text-align: justify;">Retorna @Resultado (BIT) y @Mensaje con el resultado de la validación.</p><p style="margin-bottom: 14px; text-align: justify;">Utilizado por <code style="background-color: #fff3cd; padding: 2px 6px; border-radius: 3px; color: #856404; font-size: 14px; font-weight: 500;">spMovimientos_GuardarMovimiento</code> antes de crear el movimiento.</p></div>',
NULL, 'tbAuxiliares, tbMovimientos', GETDATE(), 0),

('spMovimientos_ListarPorSocio', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene el historial de movimientos de un socio específico.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbMovimientos</code> filtrando por NumeroAsociado.</p><p style="margin-bottom: 14px; text-align: justify;">Puede aplicar filtros adicionales por auxiliar, rango de fechas, o tipo de movimiento.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna información completa de los movimientos incluyendo fechas, montos, códigos de transacción, y saldos.</p><p style="margin-bottom: 14px; text-align: justify;">Incluye manejo de excepciones.</p></div>',
NULL, 'tbMovimientos', GETDATE(), 0),

('spMovimientos_ObtenerDatosComprobante', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene los datos necesarios para generar un comprobante de movimiento.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbMovimientos</code> y hace <strong style="color: #dc3545; font-weight: 600;">JOINs</strong> con <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>, y otras tablas relacionadas para obtener información completa del movimiento, asociado, y auxiliar.</p><p style="margin-bottom: 14px; text-align: justify;">Retorna datos formateados para impresión de comprobantes.</p></div>',
NULL, 'tbMovimientos, tbAsociados, tbAuxiliares', GETDATE(), 0),

-- Asociados
('spAsociados_ObtenerEstadoCuenta', 'SP',
'<div style="line-height: 1.9; font-size: 15px; color: #333;"><p style="margin-bottom: 14px; text-align: justify;">Obtiene el estado de cuenta completo de un asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Consulta <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAsociados</code>, <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbAuxiliares</code>, y <code style="background-color: #f8f9fa; padding: 2px 6px; border-radius: 3px; color: #e83e8c; font-size: 14px; font-weight: 500;">tbMovimientos</code> para calcular saldos, intereses, y resumen financiero del asociado.</p><p style="margin-bottom: 14px; text-align: justify;">Puede incluir información de todos los auxiliares del asociado con sus respectivos saldos y movimientos recientes.</p></div>',
NULL, 'tbAsociados, tbAuxiliares, tbMovimientos', GETDATE(), 0)

PRINT 'Descripciones de objetos de BD insertadas exitosamente'
GO


